 "content": "def transform(grid):
    """Transform tiled 2-pattern grids: reconstruct the obscured tile strip and encode tile coordinates."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Derive cell tile-size from the regular one-cell separators (tile size 3/4 here).
    size = 4 if h == 19 else 3
    step = size + 1
    nrows = (h + 1) // step
    ncols = (w + 1) // step
    starts_r = [i * step for i in range(nrows)]
    starts_c = [j * step for j in range(ncols)]
    # Find a complete row or column of color 3 as the occluded strip.
    hidden_row = next((i for i, r in enumerate(starts_r)
        if all(grid[r+dr][c] == 3 for dr in range(size) for c in range(w))), None)
    hidden_col = next((j for j, c in enumerate(starts_c)
        if all(grid[r][c+dc] == 3 for r in range(h) for dc in range(size))), None)
    # Existing exemplar tile pattern, same across tile placements.
    exemplar = None
    for i, r in enumerate(starts_r):
        for j, c in enumerate(starts_c):
            if i == hidden_row or j == hidden_col:
                continue
            tile = [grid[r+dr][c:c+size] for dr in range(size)]
            if any(v == 2 for row in tile for v in row):
                exemplar = [row[:] for row in tile]
                break
        if exemplar is not None:
            break
    # Presence map for visible tile positions.
    present = [[any(grid[r+dr][c+dc] == 2 for dr in range(size) for dc in range(size))
                for c in starts_c] for r in starts_r]
    # Infer the hidden strip by matching repeated line patterns along the unhidden axis.
    if hidden_row is not None:
        candidates = [i for i in range(nrows) if i != hidden_row]
        # Duplicate the closest neighboring row's occupancy pattern.
        source = min(candidates, key=lambda i: abs(i-hidden_row))
        for j, c in enumerate(starts_c):
            if present[source][j] and exemplar is not None:
                for dr in range(size):
                    for dc in range(size): out[starts_r[hidden_row]+dr][c+dc] = exemplar[dr][dc]
            else:
                for dr in range(size):
                    for dc in range(size): out[starts_r[hidden_row]+dr][c+dc] = 0
        # Blank the separator after filled content.
        if hidden_row*step+size < h:
            for c in range(w): out[hidden_row*step+size][c] = 0
    elif hidden_col is not None:
        # Candidate pattern from adjacent known column; the demo uses the left neighbor.
        source = hidden_col-1 if hidden_col > 0 else hidden_col+1
        for i, r in enumerate(starts_r):
            if present[i][source] and exemplar is not None:
                for dr in range(size):
                    for dc in range(size): out[r+dr][starts_c[hidden_col]+dc] = exemplar[dr][dc]
            else:
                for dr in range(size):
                    for dc in range(size): out[r+dr][starts_c[hidden_col]+dc] = 0
        if hidden_col*step+size < w:
            for r in range(h): out[r][hidden_col*step+size] = 0
    # Encode tile-row/column coordinates by changing the corresponding 2 cell to 8.
    for i, r in enumerate(starts_r):
        for j, c in enumerate(starts_c):
            if any(out[r+dr][c+dc] == 2 for dr in range(size) for dc in range(size)):
                rr, cc = r + (i % size), c + (j % size)
                if out[rr][cc] == 2: out[rr][cc] = 8
    return out
