    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Tiles are separated by a one-cell zero gutter; color 3 marks an erased tile row/column.
    size = 4 if h == 19 else 3
    step = size + 1
    nr, nc = (h + 1) // step, (w + 1) // step
    rs, cs = [i * step for i in range(nr)], [j * step for j in range(nc)]
    hidden_r = next((i for i, r in enumerate(rs)
                     if all(grid[r + dr][c] == 3 for dr in range(size) for c in range(w))), None)
    hidden_c = next((j for j, c in enumerate(cs)
                     if all(grid[r][c + dc] == 3 for r in range(h) for dc in range(size))), None)
    # Any visible nonempty tile gives the repeated base pattern.
    pattern = None
    for i, r in enumerate(rs):
        for j, c in enumerate(cs):
            if i == hidden_r or j == hidden_c:
                continue
            tile = [grid[r + dr][c:c + size] for dr in range(size)]
            if any(v == 2 for row in tile for v in row):
                pattern = [row[:] for row in tile]
                break
        if pattern is not None:
            break
    if pattern is None:
        return out
    # Rebuild the erased strip using the pattern's same-coordinate cell as the occupancy bit.
    if hidden_r is not None:
        r0 = rs[hidden_r]
        for dr in range(size):
            for c in range(w):
                out[r0 + dr][c] = 0
        for j, c in enumerate(cs):
            if pattern[hidden_r][j] == 2:
                for dr in range(size):
                    out[r0 + dr][c:c + size] = pattern[dr][:]
    elif hidden_c is not None:
        c0 = cs[hidden_c]
        for r in range(h):
            for dc in range(size):
                out[r][c0 + dc] = 0
        for i, r in enumerate(rs):
            if pattern[i][hidden_c] == 2:
                for dr in range(size):
                    for dc in range(size):
                        out[r + dr][c0 + dc] = pattern[dr][dc]
    # Highlight the (tile-row, tile-column) cell within every occupied tile.
